<script setup lang="ts">
import{ref}from"vue";import{Search,Reading}from"@element-plus/icons-vue";import{api}from"@/api";import{err,text}from"@/utils/format";import type{KnowledgeResult}from"@/types/api";import PageHeader from"@/components/common/PageHeader.vue";import StateView from"@/components/common/StateView.vue";
const query=ref(''),category=ref(''),items=ref<KnowledgeResult[]>([]),loading=ref(false),error=ref(''),searched=ref(false);const categories=[['jobs','岗位知识'],['skills','技能知识'],['resume','简历指导'],['interview','面试准备'],['career','职业成长']];async function search(){if(!query.value.trim()){error.value='请输入要检索的就业问题';return}loading.value=true;error.value='';searched.value=true;try{items.value=(await api.knowledge({query:query.value,category:category.value||undefined,top_k:12})).results}catch(e){error.value=err(e)}finally{loading.value=false}}
</script><template><div><PageHeader title="就业资源中心" description="通过RAG知识库检索岗位、技能、简历、面试与职业成长资料。"/><div class="resource-search"><el-input v-model="query" size="large" :prefix-icon="Search" placeholder="例如：Java后端岗位需要哪些核心技能？" @keyup.enter="search"/><el-select v-model="category" size="large" clearable placeholder="全部资源"><el-option v-for="x in categories" :key="x[0]" :value="x[0]" :label="x[1]"/></el-select><el-button type="primary" size="large" @click="search">检索知识库</el-button></div><div v-if="!searched" class="resource-intro"><el-icon><Reading/></el-icon><h3>检索就业知识库</h3><p>输入具体问题，系统将调用 PostgreSQL + pgvector 混合检索能力返回真实资料。</p><div><button v-for="x in ['前端开发岗位技能要求','项目经历如何量化成果','技术面试准备方法']" :key="x" @click="query=x;search()">{{x}}</button></div></div><StateView v-else :loading="loading" :error="error" :empty="!items.length" empty-text="知识库中没有找到相关资料" @retry="search"><template #content><div class="resource-count">检索到 {{items.length}} 条相关知识</div><div class="resource-list"><article v-for="(x,i) in items" :key="x.document_id||x.id||i"><div class="resource-index">{{String(i+1).padStart(2,'0')}}</div><div><div class="resource-meta"><el-tag size="small">{{x.category||String(x.metadata?.category||'知识资源')}}</el-tag><span v-if="x.score">相关度 {{Math.round(x.score*100)}}%</span></div><h3>{{x.title||String(x.metadata?.title||x.doc_id||'就业知识')}}</h3><p>{{text(x.content).slice(0,420)}}</p><small>{{x.source}}</small></div></article></div></template></StateView></div></template>
